 if(kind==='person'&&referenceIdentityConflict(text,item))continue;const name=item[field]||item.word||item.character||item.char||item.text||item.content||item.hanzi;if(!name)continue;const n=referenceNorm(name);if(!n)continue;const prefix=referenceNorm(source.slice(0,item.start_index||0)).length;let at=-1;
 if(local.normalized===remote.normalized&&local.normalized.slice(prefix,prefix+n.length)===n)at=prefix;
 else {let cursor=0,score=-Infinity;while((cursor=local.normalized.indexOf(n,cursor))>=0){const before=local.normalized.slice(Math.max(0,cursor-12),cursor),after=local.normalized.slice(cursor+n.length,cursor+n.length+12);const rb=remote.normalized.slice(Math.max(0,prefix-12),prefix),ra=remote.normalized.slice(prefix+n.length,prefix+n.length+12);const q=referenceScore(before,rb)+referenceScore(after,ra)-.3*Math.abs(cursor/Math.max(1,local.normalized.length)-prefix/Math.max(1,remote.normalized.length));if(q>score){score=q;at=cursor}cursor+=n.length}}
