const referenceRenderContent=renderContent;
renderContent=function(){referenceRenderContent();paintReferenceTools();loadReferenceChapter()};
async function referenceMap(){if(!referenceState.map){const r=await fetch('data/reference-map.json');if(!r.ok)throw Error('目录补充未就绪');referenceState.map=await r.json()}return referenceState.map}
async function loadReferenceChapter(force=false){const stamp=++referenceState.stamp;if(state.book!=='epub2'||!state.settings.reference){referenceStatus.textContent='补充阅读资料';return}const loc=`${state.chapter}:${state.segment}`,local=segments[state.segment];if(local.referenceLoaded&&!force){referenceStatus.textContent='补充资料已载入';return}referenceStatus.textContent='正在补充人物与阅读资料…';try{
 const [map,people]=await Promise.all([referenceMap(),peopleIndex()]);referenceState.names=Object.keys(people.byName);referenceState.profileByQ=new Map(people.profiles.filter(p=>p.qid).map(p=>[p.qid,p]));const entry=map.segments[loc];if(!entry){referenceStatus.textContent='本节暂无补充资料';return}
 if(!referenceState.pending.has(entry.id))referenceState.pending.set(entry.id,referenceAPI('reign',{reign_tongjian_id:entry.id}).catch(e=>{referenceState.pending.delete(entry.id);throw e}));
 const data=await referenceState.pending.get(entry.id);if(stamp!==referenceState.stamp||loc!==`${state.chapter}:${state.segment}`)return;const remote=data.ExtRef_Children_contents||[];let count=0;for(const match of matchReferenceParagraphs(local.paragraphs,remote)){
 const r=local.paragraphs[match.local],p=referenceCorrectParagraph({...remote[match.remote],year_int:data.year_int});r.reference=p;referenceState.paragraphs.set(p.tongjian_id,p);if(!r.t&&p.content_fanyi){r.t=p.content_fanyi;r.translationStatus='reference'}count++}
 local.referenceLoaded=true;local.referenceCount=count;local.referenceTotal=local.paragraphs.length;const y=$('#reading').scrollTop;referenceRenderContent();paintReferenceTools();$('#reading').scrollTop=y;referenceStatus.textContent=`补充资料 ${count}/${local.paragraphs.length} 段`;
 }catch(e){if(stamp===referenceState.stamp){referenceStatus.textContent='补充资料暂不可用 · 点击重试';referenceStatus.title=e.message}}}
function paintReferenceTools(){if(!state.settings.reference)return;document.querySelectorAll('#content .paragraph').forEach(section=>{const r=segments[state.segment].paragraphs[+section.dataset.p],p=r.reference;if(!p)return;const tools=section.querySelector('.paragraph-actions');tools.querySelectorAll('.reference-tool').forEach(x=>x.remove());const id=E(p.tongjian_id);tools.insertAdjacentHTML('beforeend',(p.class_tags||[]).map(t=>`<button class="reference-tool system-tag" data-ref-tag="${E(t)}">${E(t)}</button>`).join('')+(p.ExtRef_Children_topics||[]).map((t,i)=>`<button class="reference-tool topic-tool" data-ref-topic="${id}:${i}">${E(t.title)}</button>`).join('')+`<button class="reference-tool" data-ref-material="${id}">资料${referenceMaterialCount(p)?' '+referenceMaterialCount(p):''}</button>`+(p.zhang_TJZJ_id?`<button class="reference-tool" data-ref-zhang="${E(p.zhang_TJZJ_id)}">张居正直解</button>`:'')+((p.ExtRef_Children_decisions||[]).length?`<button class="reference-tool decision-tool" data-ref-decisions="${id}">决策卡 ${p.ExtRef_Children_decisions.length}</button>`:''));})}
function referenceMaterialCount(p){return (p.background_material_references||[]).length+(p.dtjl_references||[]).length+(p.ExtRef_Children_hu_notes||[]).filter(n=>(n.ExtRef_Children_zhang_notes||[]).length||(n.ExtRef_Children_chenzhu||[]).length).length}
function referenceParts(value){const [id,index]=value.split(':');return {p:referenceState.paragraphs.get(id),index:+index}}
function referenceHTML(html){const doc=new DOMParser().parseFromString(String(html||'').replace(/\\u3000/g,'　'),'text/html');doc.querySelectorAll('script,style,iframe,object,embed').forEach(n=>n.remove());for(const el of [...doc.body.querySelectorAll('*')]){if(!['P','BR','B','STRONG','EM','I','H2','H3','H4','UL','OL','LI','BLOCKQUOTE','TABLE','TR','TD','TH','THEAD','TBODY'].includes(el.tagName)){el.replaceWith(...el.childNodes);continue}for(const a of [...el.attributes])el.removeAttribute(a.name)}return doc.body.innerHTML}
function referenceSource(){return '<p class="search-status">补充资料来源：<a href="https://www.dutongjian.com/" target="_blank" rel="noopener">读通鉴公开阅读资料 ↗</a> · 在线读取公开资料。</p>'}
function referencePaging(page,kind,value){return `<div class="reference-paging"><button data-ref-page="${kind}" data-ref-value="${E(value)}" data-page="${page.current_page-1}" ${page.current_page<=1?'disabled':''}>上一页</button><span>${page.current_page} / ${page.total_pages||1} · 共 ${page.total_paragraphs||0} 段</span><button data-ref-page="${kind}" data-ref-value="${E(value)}" data-page="${page.current_page+1}" ${page.current_page>=page.total_pages?'disabled':''}>下一页</button>${page.anchor_paragraph_order?`<button data-ref-page="${kind}" data-ref-value="${E(value)}" data-page="${Math.ceil(page.anchor_paragraph_order/page.page_size)}">当前出现</button>`:''}</div>`}
