function referenceStoreOccurrence(raw){const existing=referenceState.paragraphs.get(raw.tongjian_id);const p=referenceCorrectParagraph(existing?{...raw,...existing}:raw);referenceState.paragraphs.set(p.tongjian_id,p);return p}
function referenceOccurrences(page){return (page.items||[]).map(row=>{const raw=row.paragraph_brief?.paragraph;if(!raw)return '';const p=referenceStoreOccurrence(raw);return `<article class="person-occurrence"><div class="person-occurrence-title"><span>${E(personYear(p.year_int))}</span><button data-ref-jump="${E(p.tongjian_id)}">${E(p.path||'定位到原文')} ↗</button></div><p class="person-snippet">${referencePlainOriginal(p)}</p><details><summary>展开译文与资料</summary><p class="translated">${E(p.content_fanyi||'暂无译文')}</p><button data-ref-material="${E(p.tongjian_id)}">查看段落资料</button></details></article>`}).join('')||'<p class="empty">暂无关联段落</p>'}
async function referencePerson(value,page=1){const {p,index}=referenceParts(value),person=p?.ExtRef_Children_people?.[index];if(!person)return;const stamp=referenceState.dialogStamp+1;openDialog(person.people_name_jianti_auto||person.people_name,'<p>正在载入人物资料…</p>');try{
 if(person.local_profile){await referenceLocalPerson(person.local_profile);return}
 if(person.local_identity){const data=await peopleIndex(),ids=data.byPerson[person.local_identity]||[];const id=ids.find(i=>data.occurrences[i].c===state.chapter&&data.occurrences[i].s===state.segment)??ids[0];if(id!==undefined){await personDialog(id,person.local_identity);return}}
 if(!person.link_td_id){const full=referenceNorm(person.people_xingming||''),data=await peopleIndex(),mention=(data.byName[full]||[]).find(i=>{const m=data.occurrences[i];return m.c===state.chapter&&m.s===state.segment&&segments[state.segment].paragraphs[m.p]?.reference?.tongjian_id===p.tongjian_id});if(mention!==undefined){await personDialog(mention);return}openDialog(person.people_name_jianti_auto||person.people_name,`<p>${E(person.link_td_description||'本条身份尚未确认，请结合上下文辨认。')}</p>${referenceSource()}`);return}
 const d=await referenceAPI('resolved_people_info',{mention_tongjian_id:person.tongjian_id,link_td_id:person.link_td_id,page,page_size:7});if(stamp!==referenceState.dialogStamp||!$('#dialog').open)return;const profile=d.profile||{},profileDates=referenceCheckedDates({...person,link_birth_year:profile.birth_year,link_death_year:profile.death_year},p),rel=d.relationships||[],rows=d.occurrence_page||{items:[],current_page:1,total_pages:1};
 $('#dialog').classList.add('person-dialog');$('#dialog-body').innerHTML=`<div class="person-intro"><strong>${E(profile.name||person.people_name)}</strong> <span>${E(referenceProfileLife(profileDates))}</span>${profile.number_id?` <a href="https://wiki.dutongjian.com/id/${encodeURIComponent(profile.number_id)}" target="_blank" rel="noopener">看百科 ↗</a>`:''}<details><summary>${E((profile.biography||person.link_td_description||'暂无简介').slice(0,130))}</summary><p>${E(profile.biography||person.link_td_description||'')}</p></details></div><div class="person-layout"><aside class="person-facts"><h3>人物关系 ${rel.length} 条</h3>${rel.map(r=>`<details class="relationship"><summary>${E((r.relation_property_display_template||'{subject}的'+r.relation_property_label+'是{value}').replace('{subject}',r.source_person_name||'').replace('{value}',r.target_person_name||''))}</summary><p>${E(r.relation_detail||'')}</p>${r.source_person_number_id?`<a href="https://wiki.dutongjian.com/id/${encodeURIComponent(r.source_person_number_id)}" target="_blank" rel="noopener">${E(r.source_person_name)} ↗</a>`:''} ${r.target_person_number_id?`<a href="https://wiki.dutongjian.com/id/${encodeURIComponent(r.target_person_number_id)}" target="_blank" rel="noopener">${E(r.target_person_name)} ↗</a>`:''}</details>`).join('')||'<p>暂无关系记录</p>'}<h3>称呼</h3><p>${E((profile.alias_list||[]).join('、'))}</p>${referenceSource()}<p class="search-status">按本段人物身份编号查询。同名人物分别处理；原资料的简称关联仍须结合上下文核对。</p></aside><section class="person-occurrences">${referencePaging(rows,'person',value)}${referencePersonOccurrences(rows,person,profile)}</section></div>`;
 }catch(e){referenceError(e,()=>referencePerson(value,page))}}
async function referencePlace(value,page=1){const {p,index}=referenceParts(value),place=p?.ExtRef_Children_places?.[index];if(!place)return;const stamp=referenceState.dialogStamp+1;openDialog('地名 · '+place.place_name,'<p>正在载入地名资料…</p>');try{const d=await referenceAPI('resolved_place_info',{place_tongjian_id:place.tongjian_id,page,page_size:10});if(stamp!==referenceState.dialogStamp||!$('#dialog').open)return;const profile=d.resolved_profile||{},rows=d.occurrence_page||{items:[],current_page:1,total_pages:1};$('#dialog-body').innerHTML=`<h3>${E(profile.standard_name||d.place_name||place.place_name)}</h3><p>${E(profile.intro||place.place_note||'暂无简介')}</p><p>今地：${E(profile.modern_location||'尚无明确对应')}</p>${profile.lon_min!=null?`<p class="search-status">范围：经度 ${E(profile.lon_min)}–${E(profile.lon_max)}，纬度 ${E(profile.lat_min)}–${E(profile.lat_max)}</p>`:''}${referencePaging(rows,'place',value)}${referenceOccurrences(rows)}${referenceSource()}`;}catch(e){referenceError(e,()=>referencePlace(value,page))}}
function referenceError(e,retry){$('#dialog-body').innerHTML=`<p>${E(e.message)}</p><button class="primary" id="reference-retry">重试</button>${referenceSource()}`;$('#reference-retry').onclick=retry}
async function referenceTopic(value,page=1){const {p,index}=referenceParts(value),topic=p?.ExtRef_Children_topics?.[index];if(!topic)return;const stamp=referenceState.dialogStamp+1;openDialog('主题 · '+topic.title,'<p>正在载入主题…</p>');try{const d=await referenceAPI('topic_info',{topic_tongjian_id:topic.tongjian_id,current_paragraph_tongjian_id:p.tongjian_id,page,page_size:8});if(stamp!==referenceState.dialogStamp||!$('#dialog').open)return;$('#dialog-body').innerHTML=`<div class="reference-article">${referenceHTML(d.content)}</div>${(d.children||[]).length?'<h3>子主题</h3>'+d.children.map(t=>`<button class="topic-tool" data-ref-topic-id="${E(t.tongjian_id)}">${E(t.title)}</button>`).join(''):''}${d.occurrence_page?referencePaging(d.occurrence_page,'topic',value)+referenceOccurrences(d.occurrence_page):''}${referenceSource()}`;}catch(e){referenceError(e,()=>referenceTopic(value,page))}}
function referenceMaterial(id){const p=referenceState.paragraphs.get(id);if(!p)return;openDialog('注释与关联资料',`<h3>原文</h3><p class="original">${referencePlainOriginal(p)}</p><details><summary>原网站参考译文</summary><p>${E(p.content_fanyi||'暂无译文')}</p></details><h3>胡三省、章钰及陈垣注释</h3>${(p.ExtRef_Children_hu_notes||[]).map(n=>`<details><summary>${E(n.note_type||'注释')} · ${E((n.note_content||'').slice(0,65))}</summary><p class="annotation-full">${displayText(n.note_content||'')}</p>${(n.ExtRef_Children_zhang_notes||[]).map(v=>`<p>章钰：${E(v.note_content||v.zhang_note_content||v.content||v.text||'')}</p>`).join('')}${(n.ExtRef_Children_chenzhu||[]).map(v=>`<h4>陈垣 · ${E(v.chapter_name)}</h4><p>${E(v.chenzhu_text)}</p>`).join('')}</details>`).join('')||'<p>暂无补充注释</p>'}<h3>关联资料库</h3>${(p.background_material_references||[]).map(b=>`<details><summary>${E(b.display_title||b.path)}</summary>${(b.excerpts||[]).map(e=>`<p>${E(e.context_before)}<mark>${E(e.source_text)}</mark>${E(e.context_after)}</p><button data-ref-passage="${E(e.source_paragraph_tongjian_id)}">阅读全文</button>`).join('')}</details>`).join('')||'<p>暂无关联资料</p>'}<h3>读通鉴论</h3>${(p.dtjl_references||[]).map(d=>`<details><summary>${E(d.title||d.display_title||d.path||'读通鉴论')}</summary>${(d.excerpts||[]).map(x=>`<p>${E(x.context_before)}<mark>${E(x.source_text)}</mark>${E(x.context_after)}</p>`).join('')}<button data-ref-comment-title="${E(d.title)}">在《读通鉴论》中查找全文</button></details>`).join('')||'<p>暂无关联评论</p>'}<h3>官职释义</h3>${(p.ExtRef_Children_officials||[]).map(o=>`<details><summary>${E(o.official_name)} · ${E(o.official_category)}</summary><p>${E(o.official_note)}</p></details>`).join('')||'<p>暂无官职记录</p>'}${(p.reading_annotation_sources||[]).map(s=>`<button data-ref-annotations="${E(id)}" data-source-key="${E(s.source_key||s.key||'')}">${E(s.display_name||s.source_name||s.title||'批读资料')}</button>`).join('')}${referenceSource()}`)}
async function referenceArticle(endpoint,params,title){const stamp=referenceState.dialogStamp+1;openDialog(title,'<p>正在载入…</p>');try{const d=await referenceAPI(endpoint,params);if(stamp!==referenceState.dialogStamp||!$('#dialog').open)return;let articles=[];function visit(v){if(Array.isArray(v)){v.forEach(visit);return}if(v&&typeof v==='object'){for(const [k,x]of Object.entries(v)){if(['paragraph_content','content_jianti','content_fanyi','content','text','annotation_content','annotation_text','passage_content','decision_content','description'].includes(k)&&typeof x==='string')articles.push(x);else if(typeof x==='object')visit(x)}}}visit(d);$('#dialog-body').innerHTML=`<div class="reference-article">${[...new Set(articles)].map(referenceHTML).join('<hr>')||'<p>本条资料没有可显示的正文。</p>'}</div>${referenceSource()}`;}catch(e){referenceError(e,()=>referenceArticle(endpoint,params,title))}}
async function referenceJump(id){const p=referenceState.paragraphs.get(id);if(!p)return;try{const [map,locator]=await Promise.all([referenceMap(),referenceAPI('paragraph_locator',{ref:id})]);const target=map.reverse[locator.reign_tongjian_id];if(!target)throw Error('未找到本地对应章节');$('#dialog').close();await navigate('epub2',target.chapter,target.segment,0);const a=referenceNorm(p.content),rows=segments[state.segment].paragraphs;let best=0,score=0;rows.forEach((r,i)=>{const q=referenceScore(referenceNorm(r.o),a);if(q>score){best=i;score=q}});if(score<.7){toast('已定位年份，请结合原文寻找对应段落');return}jumpTo(best);history.replaceState(null,'','#'+key(best));}catch(e){toast(e.message)}}
function referenceOverview(){const seg=segments[state.segment],count=seg?.referenceCount;openDialog('补充阅读资料',`<p>人物年龄、生卒年、亲属关系、地名、官职、主题、系统标签和关联注释，按当前章节从原网站公开阅读资料取得。</p><p>首次访问需要联网，已访问资料保存在本机；EPUB 原文、书签和个人批注仍使用本地内容。</p>${count!=null?`<p>当前 ${count}/${seg.referenceTotal} 段已匹配。</p>`:''}<div class="reading-checks"><label><input id="reference-enabled" type="checkbox" ${state.settings.reference?'checked':''}>显示补充阅读资料</label></div><button id="reference-load" class="primary">重新载入本节资料</button><h3>功能对照</h3><p>正文阅读、文白联动、人物及地名查询、官职释义、主题与关联资料均可在当前页使用。沙盘态势已加入地图标绘、记录、自动保存和导入导出；账号同步、AI问答和古本影像仍需独立接入。</p><p><a href="comparison.html" target="_blank" rel="noopener">查看逐项对照清单 ↗</a></p>${referenceSource()}`);$('#reference-enabled').onchange=e=>{state.settings.reference=e.target.checked;persist();redrawReading()};$('#reference-load').onclick=()=>{$('#dialog').close();loadReferenceChapter(true)}}
actions.reference=referenceOverview;
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;let handled=true;if(el.dataset.refPerson)referencePerson(el.dataset.refPerson);else if(el.dataset.refPlace)referencePlace(el.dataset.refPlace);else if(el.dataset.refOfficial){const {p,index}=referenceParts(el.dataset.refOfficial),o=p?.ExtRef_Children_officials?.[index];if(o)openDialog('官职 · '+o.official_name,`<p>${E(o.official_category)} · ${E(o.official_rank||'')}</p><p>${E(o.official_note)}</p>${referenceSource()}`)}else if(el.dataset.refMaterial)referenceMaterial(el.dataset.refMaterial);else if(el.dataset.refTopic)referenceTopic(el.dataset.refTopic);else if(el.dataset.refTopicId){const p={tongjian_id:'topic-'+el.dataset.refTopicId,ExtRef_Children_topics:[{tongjian_id:el.dataset.refTopicId,title:el.textContent}]};referenceState.paragraphs.set(p.tongjian_id,p);referenceTopic(p.tongjian_id+':0')}else if(el.dataset.refPage){const fn={person:referencePerson,place:referencePlace,topic:referenceTopic,tag:referenceTag}[el.dataset.refPage];fn?.(el.dataset.refValue,+el.dataset.page)}else if(el.dataset.refJump)referenceJump(el.dataset.refJump);else if(el.dataset.refZhang)referenceArticle('zhang_tjzj_detail',{zhang_tjzj_id:el.dataset.refZhang},'张居正 · 资治通鉴直解');else if(el.dataset.refCommentTitle)referenceFindComment(el.dataset.refCommentTitle);else if(el.dataset.refDecisionId)referenceDecision(el.dataset.refDecisionId);else if(el.dataset.refPassage)referencePassage({tongjian_id:el.dataset.refPassage});else if(el.dataset.refAnnotations)referenceArticle('reading_annotations',{target_id:el.dataset.refAnnotations,source_key:el.dataset.sourceKey},el.textContent);else if(el.dataset.refDecisions){const p=referenceState.paragraphs.get(el.dataset.refDecisions);openDialog('决策卡',`<p>${E(segments[state.segment].title)}</p>${(p?.ExtRef_Children_decisions||[]).map(d=>`<details><summary>${E(d.decision_name||d.title||d.decision_title||d.name||'历史决策')}</summary><button data-ref-decision-id="${E(d.decision_tongjian_id||d.tongjian_id)}">查看选项与历史结果</button></details>`).join('')}${referenceSource()}`)}else if(el.dataset.refTag)referenceTag(el.dataset.refTag);else handled=false;if(handled){e.preventDefault();e.stopImmediatePropagation()}},true);
const backupTools=document.createElement('div');backupTools.className='reference-resource-tools';backupTools.innerHTML='<button data-action="reference">人物与补充资料</button><button data-action="lexicon">字词查询</button><button data-action="backup">导出／导入阅读记录</button><a href="comparison.html" target="_blank" rel="noopener">功能对照说明 ↗</a><a href="person-audit.html" target="_blank" rel="noopener">人物核查记录 ↗</a>';$('#tools .tool-body').append(backupTools);
actions.lexicon=()=>{openDialog('字词查询','<form id="lexicon-form" class="row"><input id="lexicon-query" aria-label="查询字词" placeholder="输入字词，如：縯、大司徒"><button class="primary">查询</button></form><div id="lexicon-result"></div>');$('#lexicon-form').onsubmit=async e=>{e.preventDefault();const q=$('#lexicon-query').value.trim(),result=$('#lexicon-result');if(!q)return;result.textContent='正在查询…';try{const d=await referenceAPI('lexicon/lookup',{query:q});if(!result.isConnected||$('#lexicon-query')?.value.trim()!==q)return;const entries=d.entries||d.entry_list||[];result.innerHTML=entries.map(v=>`<h3>${E(v.headword||v.word||q)}</h3>${referenceHTML(v.content||v.definition||v.text||'')}`).join('')||'<p>暂无词条，可查阅胡注或通鉴百科。</p>'}catch(e){if(result.isConnected)result.textContent=e.message}}};
function mergeReadingBackup(text){const d=JSON.parse(text);if(d.format!=='tongjian-reader-backup'||!d.saved)throw Error('请选择本阅读器导出的记录');for(const type of ['bookmarks','notes','last'])for(const [k,v]of Object.entries(d.saved[type]||{}))if(v&&typeof v==='object'&&(!state[type][k]||(v.date||0)>(state[type][k].date||0)))state[type][k]=v;for(const [k,v]of Object.entries(d.saved.tags||{}))if(Array.isArray(v))state.tags[k]=[...new Set([...(state.tags[k]||[]),...v.filter(t=>typeof t==='string')])];for(const [k,v]of Object.entries(d.saved.settings||{}))if(Object.hasOwn(state.settings,k)&&typeof v===typeof state.settings[k]&&(typeof v!=='number'||Number.isFinite(v)))state.settings[k]=v;state.visited={...state.visited,...d.saved.visited};state.seconds=Math.max(state.seconds,Number(d.saved.seconds)||0);persist();$('#dialog').close();redrawReading();toast('阅读记录已合并')}
actions.backup=()=>{openDialog('阅读记录备份','<p>将书签、批注、标签、设置和进度保存成文件，可在另一台电脑导入。</p><button id="export-reading" class="primary">导出阅读记录</button><p><label>导入阅读记录 <input id="import-reading" type="file" accept=".json"></label></p><details id="backup-text-details"><summary>文本备份与导入（浏览器无法下载时使用）</summary><p>导出后可复制下方完整内容保存；也可粘贴已有备份，再点击导入。</p><textarea id="backup-text" aria-label="阅读记录备份内容" rows="8" style="width:100%;font-family:monospace"></textarea><button id="import-reading-text">导入粘贴的备份</button></details><p class="search-status">导入按记录时间合并，不删除当前书签与批注；阅读设置采用备份值。</p>');$('#export-reading').onclick=()=>{persist();const text=JSON.stringify({format:'tongjian-reader-backup',version:1,saved:JSON.parse(localStorage.getItem(KEY))},null,2);$('#backup-text').value=text;$('#backup-text-details').open=true;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download='通鉴阅读记录-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000);toast('备份已生成，可下载或复制文本保存')};$('#import-reading').onchange=async e=>{try{if(e.target.files[0])mergeReadingBackup(await e.target.files[0].text())}catch(e){toast(e.message)}};$('#import-reading-text').onclick=()=>{try{mergeReadingBackup($('#backup-text').value)}catch(e){toast(e.message)}}};

if(segments[state.segment])renderContent();
function referenceIdentityConflict(text,item,profile=null){const short=referenceNorm(item.people_name||''),full=referenceNorm(profile?.name||item.people_xingming||(item.link_td_description||'').split(/[，,。；;]/)[0]);if(!short||short.length>2||full.length<=short.length||!full.endsWith(short)||referenceNorm(text).includes(full))return false;if(!referenceState.suffixes.has(short))referenceState.suffixes.set(short,referenceState.names.filter(n=>n.length>short.length&&n.length<=4&&n.endsWith(short)));return referenceState.suffixes.get(short).some(n=>n!==full&&referenceNorm(text.slice(0,140)).includes(n))}
function referencePronounce(text,p){if(!state.settings.pinyin)return displayText(text);let cursor=0,out='';const matches=(p.ExtRef_Children_pinyin||[]).filter(x=>x.text&&text.includes(x.text));for(const m of matches){const at=text.indexOf(m.text,cursor);if(at<0)continue;out+=displayText(text.slice(cursor,at))+`<ruby>${displayText(m.text)}<rt>${E(m.pinyin||'')}</rt></ruby>`;cursor=at+m.text.length}return out+displayText(text.slice(cursor))}
function referencePlainOriginal(p){const text=String(p.content||'').replace(/^\d+/,''),ranges=referenceRanges(text,p);let cursor=0,out='';for(const r of ranges){if(r.start<cursor)continue;out+=readingText(text.slice(cursor,r.start))+referenceEntity(text.slice(r.start,r.end),r,p);cursor=r.end}return out+readingText(text.slice(cursor))}
function referencePersonOccurrences(page,person,profile){let hidden=0;const items=(page.items||[]).filter(row=>{const raw=row.paragraph_brief?.paragraph,p=raw?referenceCorrectParagraph(raw):null;const names=(p?.ExtRef_Children_people||[]).filter(x=>x.link_td_id===person.link_td_id);const lostIdentity=raw?.ExtRef_Children_people?.some(x=>x.link_td_id===person.link_td_id)&&!names.length;const conflict=lostIdentity||names.length&&names.every(x=>referenceIdentityConflict(p.content,x,profile));if(conflict)hidden++;return !conflict});return (hidden?`<p class="search-status">本页有 ${hidden} 条简称疑似混同，已暂时隐藏。</p>`:'')+referenceOccurrences({...page,items})}
async function referenceDecision(id){const stamp=referenceState.dialogStamp+1;openDialog('历史决策','<p>正在载入…</p>');try{const rows=await referenceAPI('decisions',{decision_tongjian_id:id,limit:1});if(stamp!==referenceState.dialogStamp||!$('#dialog').open)return;const d=rows[0];if(!d)throw Error('暂无决策资料');$('#dialog-title').textContent=d.decision_name;$('#dialog-body').innerHTML=`<p>${E(d.role_name)} · ${E(personYear(d.year_int))}</p><p>${E(d.background)}</p>${(d.detail?.options||[]).map((o,i)=>`<details><summary>选项 ${i+1}：${E(o.choice)}</summary><p>支持理由：${E(o.support_point)}</p><p>反对理由：${E(o.oppose_point)}</p></details>`).join('')}<details><summary>查看历史选择</summary><p>${E(d.detail?.final_choice||'暂无记录')}</p></details>${referenceSource()}`;}catch(e){referenceError(e,()=>referenceDecision(id))}}
async function referenceFindComment(title){const phrase=referenceNorm(title.replace(/^[一二三四五六七八九十百\d]+\s*/,''));const b=state.books.find(b=>b.id==='lun');let candidates=[];for(let c=0;c<b.chapters.length;c++)for(let s=0;s<b.chapters[c].segments.length;s++){const t=referenceNorm(b.chapters[c].segments[s]);if(t.includes(phrase)||phrase.includes(t)&&t.length>3)candidates.push({book:'lun',chapter:c,segment:s,paragraph:0,title:b.chapters[c].segments[s]})}if(candidates.length){openDialog('读通鉴论 · '+title,candidates.map(r=>`<button class="result" data-location="${E(JSON.stringify(r))}">${E(r.title)}</button>`).join(''));return}searchDialog(phrase.slice(0,12));}
async function referenceTag(tag,page=1){const stamp=referenceState.dialogStamp+1;openDialog('系统标签 · '+tag,'<p>正在查找全书关联段落…</p>');try{const d=await referenceAPI('class_tag_info',{tag_value:tag,page,page_size:8});if(stamp!==referenceState.dialogStamp||!$('#dialog').open)return;const rows=d.occurrence_page;$('#dialog-body').innerHTML=`<p>${E(d.description||d.tag_description||'全书同类历史事件与段落')}</p>${rows?referencePaging(rows,'tag',tag)+referenceOccurrences(rows):'<p>暂无相关段落</p>'}${referenceSource()}`;}catch(e){referenceError(e,()=>referenceTag(tag,page))}}
let atlasData=null,atlasStamp=0;
async function atlasDialog(){if(!atlasData){const r=await fetch('data/atlas.json');atlasData=await r.json()}const map=await referenceMap(),year=map.segments[`${state.chapter}:${state.segment}`]?.year;let index=atlasData.findIndex(x=>year>=x.start_year_int&&year<=x.end_year_int);if(index<0)index=0;openDialog('历史地图',`<div class="atlas-controls"><select id="atlas-period" aria-label="地图时代">${atlasData.map((p,i)=>`<option value="${i}" ${i===index?'selected':''}>${E(p.name)}</option>`).join('')}</select><select id="atlas-sheet" aria-label="地图名称"></select><button id="atlas-minus" aria-label="缩小地图">−</button><button id="atlas-plus" aria-label="放大地图">＋</button><span id="atlas-zoom">100%</span></div><p id="atlas-status" class="search-status">请选择地图</p><div class="atlas-canvas"><img id="atlas-image" alt="历史地图" hidden></div><p class="search-status">图片来源：原网站历史地图；放大后可滚动查看。首次查看需要联网。</p>`);$('#dialog').classList.add('atlas-dialog');let zoom=100;const changeZoom=n=>{zoom=Math.max(50,Math.min(400,n));$('#atlas-image').style.width=zoom+'%';$('#atlas-zoom').textContent=zoom+'%'};const loadSheet=async()=>{const group=atlasData[+$('#atlas-period').value],item=group.items[+$('#atlas-sheet').value],stamp=++atlasStamp;$('#atlas-status').textContent='正在载入 '+item.title+'…';$('#atlas-image').hidden=true;try{const d=await referenceAPI('map/image-url',{oss_filename:item.oss_filename});if(stamp!==atlasStamp||!$('#atlas-image'))return;const image=$('#atlas-image');image.onload=()=>{if(stamp===atlasStamp){image.hidden=false;$('#atlas-status').textContent=item.title}};image.onerror=()=>{if(stamp===atlasStamp)$('#atlas-status').textContent='地图暂时无法载入，请重新选择或稍后重试。'};image.alt=item.title;image.src=d.image_url;changeZoom(100)}catch(e){if(stamp===atlasStamp&&$('#atlas-status'))$('#atlas-status').textContent=e.message}};const loadGroup=()=>{const group=atlasData[+$('#atlas-period').value];$('#atlas-sheet').innerHTML=group.items.map((x,i)=>`<option value="${i}">${E(x.title)}</option>`).join('');loadSheet()};$('#atlas-period').onchange=loadGroup;$('#atlas-sheet').onchange=loadSheet;$('#atlas-minus').onclick=()=>changeZoom(zoom-25);$('#atlas-plus').onclick=()=>changeZoom(zoom+25);loadGroup()}
