async function officialsDialog(){openDialog('历代官制','<div class="row"><select id="officials-dynasty" aria-label="官制时代">'+[['zhou','周'],['qin','秦'],['xihan','西汉'],['donghan','东汉'],['sanguo','三国'],['xijin','西晋'],['dongjin','东晋十六国'],['nanbeichao','南北朝'],['sui','隋'],['tang','唐'],['wudaishiguo','五代十国']].map(([id,name])=>`<option value="${id}">${name}</option>`).join('')+'</select><input id="officials-filter" aria-label="筛选官职" placeholder="查找官职或机构"></div><div id="officials-tree"></div>');const box=$('#officials-tree'),select=$('#officials-dynasty');let data=null;const draw=()=>{if(!data||!box.isConnected)return;const q=$('#officials-filter').value.trim();function node(n){const kids=(n.children||[]).map(node).join(''),self=!q||[n.name,n.description,JSON.stringify(n.details||{})].join('').includes(q);if(!self&&!kids)return '';return `<details class="official-node" ${q?'open':''}><summary>${E(n.name)}</summary><p>${E(n.description||'')}</p>${Object.entries(n.details||{}).map(([k,v])=>`<p>${E(typeof v==='string'?v:JSON.stringify(v))}</p>`).join('')}<div>${kids}</div></details>`}box.innerHTML=`<h3>${E(data.title)}</h3><p>${E(data.meta?.period||'')}</p>${(data.meta?.notes||[]).map(n=>`<p>${E(n)}</p>`).join('')}${node(data.root)||'<p>没有找到匹配的官职</p>'}${referenceSource()}`};select.onchange=async()=>{const value=select.value;box.textContent='正在载入…';try{const r=await fetch('data/officials/'+value+'.json');const d=await r.json();if(!box.isConnected||select.value!==value)return;data=d;draw()}catch(e){if(box.isConnected)box.textContent='官制资料暂时无法载入'}};$('#officials-filter').oninput=draw;select.onchange()}
